// Short notes shown when a viewer opens a constellation or a deep sky object.
//
// The interface translator in src/i18n.js substitutes known phrases inside
// arbitrary text, which suits labels but not prose, so full sentences live here
// as explicit [pl, en, de, es] rows keyed by the same stable identifiers the sky
// data uses: the IAU Latin name for a figure, the catalogue id for an object.
//
// Each note states what a viewer would actually find there - the brightest star,
// a landmark object, an origin. Measured quantities (magnitude, apparent size,
// coordinates) are read from the catalogues at runtime and are not repeated here.
const languageIndex = {pl: 0, en: 1, de: 2, es: 3};

export const constellationNotes = Object.freeze({
 'Andromeda': ['Przykuta królewna z mitu o Perseuszu; kryje galaktykę Andromedy, najdalszy obiekt widoczny gołym okiem.', 'The chained princess of the Perseus myth, and host to the Andromeda Galaxy, the most distant thing the unaided eye can reach.', 'Die angekettete Königstochter aus dem Perseus-Mythos; sie beherbergt die Andromedagalaxie, das fernste mit bloßem Auge sichtbare Objekt.', 'La princesa encadenada del mito de Perseo; alberga la Galaxia de Andrómeda, el objeto más lejano visible a simple vista.'],
 'Antlia': ['Pompa próżniowa, jeden z instrumentów naukowych, którymi Lacaille wypełnił południowe niebo w latach 50. XVIII wieku.', 'The air pump, one of the scientific instruments Lacaille scattered across the southern sky in the 1750s.', 'Die Luftpumpe, eines der wissenschaftlichen Instrumente, mit denen Lacaille in den 1750er Jahren den Südhimmel füllte.', 'La máquina neumática, uno de los instrumentos científicos con que Lacaille pobló el cielo austral en la década de 1750.'],
 'Apus': ['Ptak rajski z katalogu Keysera i de Houtmana, spisanego podczas holenderskich wypraw do Indii Wschodnich.', 'The bird of paradise, catalogued by Keyser and de Houtman during the Dutch voyages to the East Indies.', 'Der Paradiesvogel, von Keyser und de Houtman auf den niederländischen Ostindienfahrten katalogisiert.', 'El ave del paraíso, catalogada por Keyser y de Houtman durante los viajes neerlandeses a las Indias Orientales.'],
 'Aquarius': ['Zodiakalny nosiciel wody; jego najciekawszym obiektem jest bliska mgławica planetarna Helix.', 'The zodiacal water bearer, whose finest object is the nearby Helix planetary nebula.', 'Der Wassermann des Tierkreises; sein schönstes Objekt ist der nahe Helixnebel.', 'El aguador del zodiaco; su mejor objeto es la cercana nebulosa planetaria Hélice.'],
 'Aquila': ['Orzeł Zeusa, przecięty Drogą Mleczną; jego Altair zamyka Trójkąt Letni.', "Zeus's eagle, straddling the Milky Way; its star Altair closes the Summer Triangle.", 'Der Adler des Zeus, mitten in der Milchstraße; sein Stern Atair schließt das Sommerdreieck.', 'El águila de Zeus, cruzada por la Vía Láctea; su estrella Altair cierra el Triángulo del Verano.'],
 'Ara': ['Ołtarz, na którym bogowie mieli przysięgać przed wojną z tytanami; leży w bogatym polu Drogi Mlecznej.', 'The altar on which the gods were said to swear before the war with the Titans, set in a rich Milky Way field.', 'Der Altar, auf dem die Götter vor dem Titanenkampf geschworen haben sollen, in einem reichen Milchstraßenfeld.', 'El altar sobre el que los dioses habrían jurado antes de la guerra con los titanes, en un rico campo de la Vía Láctea.'],
 'Aries': ['Baran ze złotym runem; jego punkt równonocy wiosennej dawno przesunął się precesją do Ryb.', 'The ram of the golden fleece; precession long ago carried its vernal equinox point into Pisces.', 'Der Widder mit dem Goldenen Vlies; die Präzession hat seinen Frühlingspunkt längst in die Fische verschoben.', 'El carnero del vellocino de oro; la precesión trasladó hace mucho su punto vernal a Piscis.'],
 'Auriga': ['Woźnica z jasną Kapellą i sznurem gromad otwartych leżących wzdłuż zimowej Drogi Mlecznej.', 'The charioteer, marked by brilliant Capella and a chain of open clusters along the winter Milky Way.', 'Der Fuhrmann mit der hellen Capella und einer Kette offener Sternhaufen entlang der Wintermilchstraße.', 'El auriga, con la brillante Capella y una hilera de cúmulos abiertos a lo largo de la Vía Láctea invernal.'],
 'Boötes': ['Wolarz prowadzący niedźwiedzicę wokół bieguna; jego pomarańczowy Arktur jest najjaśniejszą gwiazdą północnego nieba.', 'The herdsman driving the bear around the pole; his orange Arcturus is the brightest star of the northern sky.', 'Der Bärenhüter, der die Bärin um den Pol treibt; sein oranger Arktur ist der hellste Stern des Nordhimmels.', 'El boyero que guía a la osa alrededor del polo; su anaranjado Arturo es la estrella más brillante del cielo boreal.'],
 'Caelum': ['Rylec grawera, jeden z najmniejszych i najuboższych gwiazdozbiorów, bez gwiazdy jaśniejszej niż czwarta wielkość.', "The engraver's chisel, among the smallest and emptiest constellations, with no star brighter than fourth magnitude.", 'Der Grabstichel, eines der kleinsten und leersten Sternbilder, ohne Stern heller als vierte Größe.', 'El buril del grabador, de las constelaciones más pequeñas y vacías, sin ninguna estrella más brillante que la cuarta magnitud.'],
 'Camelopardalis': ['Żyrafa wypełniająca pustą przestrzeń między Wielką Niedźwiedzicą a Kasjopeją; wprowadził ją Plancius w 1612 roku.', 'The giraffe, filling the empty ground between the Great Bear and Cassiopeia; introduced by Plancius in 1612.', 'Die Giraffe füllt die leere Fläche zwischen Großem Bären und Kassiopeia; 1612 von Plancius eingeführt.', 'La jirafa, que llena el vacío entre la Osa Mayor y Casiopea; introducida por Plancius en 1612.'],
 'Cancer': ['Najsłabszy gwiazdozbiór zodiaku, wart obejrzenia dla gromady Żłóbek widocznej gołym okiem jako mglista plama.', 'The faintest zodiac constellation, worth finding for the Beehive cluster, a misty patch to the unaided eye.', 'Das schwächste Tierkreissternbild, sehenswert wegen der Praesepe, die dem bloßen Auge als nebliger Fleck erscheint.', 'La constelación más débil del zodiaco, buscada por el cúmulo del Pesebre, una mancha nebulosa a simple vista.'],
 'Canes Venatici': ['Psy gończe Wolarza; mieszczą Galaktykę Wir, pierwszą, w której rozpoznano budowę spiralną.', "The herdsman's hunting dogs, holding the Whirlpool Galaxy, the first in which spiral structure was recognised.", 'Die Jagdhunde des Bärenhüters; hier steht die Whirlpool-Galaxie, in der zuerst Spiralstruktur erkannt wurde.', 'Los perros de caza del boyero; contienen la Galaxia del Remolino, la primera en la que se reconoció estructura espiral.'],
 'Canis Major': ['Większy pies Oriona, prowadzony przez Syriusza — najjaśniejszą gwiazdę całego nieba.', "Orion's larger dog, led by Sirius, the brightest star in the entire sky.", 'Der größere Hund des Orion, angeführt von Sirius, dem hellsten Stern des ganzen Himmels.', 'El perro mayor de Orión, encabezado por Sirio, la estrella más brillante de todo el cielo.'],
 'Canis Minor': ['Mniejszy pies Oriona, właściwie tylko dwie gwiazdy; jaśniejsza z nich, Procjon, domyka Trójkąt Zimowy.', "Orion's smaller dog, in practice just two stars; the brighter, Procyon, completes the Winter Triangle.", 'Der kleinere Hund des Orion, praktisch nur zwei Sterne; der hellere, Prokyon, vollendet das Winterdreieck.', 'El perro menor de Orión, en la práctica solo dos estrellas; la más brillante, Proción, completa el Triángulo de Invierno.'],
 'Capricornus': ['Morski kozioł zodiaku, blady i trójkątny; zwrotnik Koziorożca nosi jego imię z czasów, gdy stało tam Słońce w przesileniu.', 'The zodiac sea goat, faint and wedge-shaped; the Tropic of Capricorn is named from when the solstice Sun stood here.', 'Der Steinbock des Tierkreises, blass und keilförmig; der Wendekreis trägt seinen Namen aus der Zeit, als hier die Sonnenwende lag.', 'La cabra marina del zodiaco, débil y triangular; el trópico de Capricornio se nombró cuando el Sol del solsticio estaba aquí.'],
 'Carina': ['Kil rozbitego okrętu Argo; mieści Kanopusa i rozległą Mgławicę Kila wokół niestabilnej gwiazdy η Carinae.', 'The keel of the broken-up ship Argo, holding Canopus and the vast Carina Nebula around the unstable star Eta Carinae.', 'Der Kiel des zerlegten Schiffs Argo; hier stehen Kanopus und der weite Carinanebel um den instabilen Stern Eta Carinae.', 'La quilla del desmembrado navío Argo; contiene Canopo y la vasta Nebulosa de Carina en torno a la inestable Eta Carinae.'],
 'Cassiopeia': ['Chełpliwa królowa, rysowana jako litera W; okrążając biegun, nie zachodzi nigdy z umiarkowanych szerokości północnych.', 'The boastful queen, drawn as a W; circling the pole, she never sets from mid-northern latitudes.', 'Die prahlerische Königin, als W gezeichnet; sie umkreist den Pol und geht in mittleren Nordbreiten nie unter.', 'La reina jactanciosa, dibujada como una W; rodea el polo y nunca se pone desde latitudes medias del norte.'],
 'Centaurus': ['Centaur mieszczący Alfę Centauri, najbliższy Słońcu układ gwiazd, i olbrzymią gromadę Omega Centauri.', 'The centaur, home to Alpha Centauri, the nearest star system to the Sun, and to the huge Omega Centauri cluster.', 'Der Zentaur beherbergt Alpha Centauri, das sonnennächste Sternsystem, und den riesigen Kugelsternhaufen Omega Centauri.', 'El centauro alberga Alfa Centauri, el sistema estelar más próximo al Sol, y el enorme cúmulo Omega Centauri.'],
 'Cepheus': ['Król Etiopii; jego δ Cephei jest pierwowzorem cefeid, gwiazd pulsujących, na których oparto skalę odległości we Wszechświecie.', 'The Ethiopian king; his Delta Cephei is the prototype Cepheid, the pulsating stars the cosmic distance scale rests on.', 'Der König Äthiopiens; sein Delta Cephei ist der Prototyp der Cepheiden, auf denen die kosmische Entfernungsskala beruht.', 'El rey de Etiopía; su Delta Cephei es el prototipo de las cefeidas, base de la escala de distancias del universo.'],
 'Cetus': ['Morski potwór wysłany na Andromedę; jego Mira była pierwszą rozpoznaną gwiazdą zmienną długookresową.', 'The sea monster sent against Andromeda; its star Mira was the first long-period variable ever recognised.', 'Das gegen Andromeda gesandte Seeungeheuer; sein Stern Mira war der erste erkannte langperiodische Veränderliche.', 'El monstruo marino enviado contra Andrómeda; su estrella Mira fue la primera variable de largo período reconocida.'],
 'Chamaeleon': ['Mały kameleon przy biegunie południowym, sąsiadujący z jednym z najbliższych obłoków gwiazdotwórczych.', 'A small chameleon near the southern pole, next to one of the closest star-forming clouds.', 'Ein kleines Chamäleon nahe dem Südpol, benachbart einer der nächstgelegenen Sternentstehungswolken.', 'Un pequeño camaleón cerca del polo sur, junto a una de las nubes de formación estelar más cercanas.'],
 'Circinus': ['Cyrkiel kreślarski wciśnięty tuż obok Alfy Centauri; drugi najmniejszy gwiazdozbiór południowego nieba.', "A draughtsman's compasses squeezed in beside Alpha Centauri; the second smallest constellation of the southern sky.", 'Der Zirkel, dicht neben Alpha Centauri eingeklemmt; das zweitkleinste Sternbild des Südhimmels.', 'El compás de dibujo, encajado junto a Alfa Centauri; la segunda constelación más pequeña del cielo austral.'],
 'Columba': ['Gołąb Noego, wydzielony z Wielkiego Psa przez Plancjusza pod koniec XVI wieku.', "Noah's dove, cut out from Canis Major by Plancius late in the sixteenth century.", 'Die Taube Noahs, im späten 16. Jahrhundert von Plancius aus dem Großen Hund herausgelöst.', 'La paloma de Noé, separada del Can Mayor por Plancius a finales del siglo XVI.'],
 'Coma Berenices': ['Ofiarowany bogom warkocz królowej Bereniki; patrzy się tu wprost na północny biegun galaktyczny i tysiące odległych galaktyk.', "Queen Berenice's hair, offered to the gods; the view here looks straight out of the galactic north pole onto thousands of distant galaxies.", 'Das den Göttern geweihte Haar der Königin Berenike; der Blick geht hier direkt zum galaktischen Nordpol auf Tausende ferner Galaxien.', 'La cabellera de la reina Berenice, ofrecida a los dioses; la vista apunta al polo norte galáctico y a miles de galaxias lejanas.'],
 'Corona Australis': ['Południowa korona, delikatny łuk gwiazd u stóp Strzelca, otoczony ciemnym obłokiem pyłu.', 'The southern crown, a delicate arc of stars at the feet of Sagittarius, wrapped in a dark dust cloud.', 'Die Südliche Krone, ein zarter Sternbogen zu Füßen des Schützen, in eine dunkle Staubwolke gehüllt.', 'La Corona Austral, un delicado arco de estrellas a los pies de Sagitario, envuelto en una nube oscura de polvo.'],
 'Corona Borealis': ['Korona północna, wyraźny półokrąg z Gemmą pośrodku; kryje T CrB, nawracającą nową wybuchającą co kilkadziesiąt lat.', 'The northern crown, a clear semicircle centred on Gemma; it holds T CrB, a recurrent nova that erupts every few decades.', 'Die Nördliche Krone, ein deutlicher Halbkreis um Gemma; hier steht T CrB, eine wiederkehrende Nova mit Ausbrüchen alle paar Jahrzehnte.', 'La Corona Boreal, un semicírculo nítido centrado en Gemma; contiene T CrB, nova recurrente que estalla cada pocas décadas.'],
 'Corvus': ['Kruk, zwarty czworobok gwiazd wysłany przez Apollina po wodę i ukarany za spóźnienie.', 'The raven, a compact quadrilateral, sent by Apollo for water and punished for returning late.', 'Der Rabe, ein kompaktes Viereck, von Apollo nach Wasser geschickt und für seine Verspätung bestraft.', 'El cuervo, un cuadrilátero compacto, enviado por Apolo a por agua y castigado por tardar.'],
 'Crater': ['Puchar Apollina, blada czasza gwiazd oparta na grzbiecie Hydry.', "Apollo's cup, a pale bowl of stars resting on the back of Hydra.", 'Der Becher Apollos, eine blasse Sternschale auf dem Rücken der Wasserschlange.', 'La copa de Apolo, un pálido cuenco de estrellas apoyado en el lomo de Hidra.'],
 'Crux': ['Najmniejszy gwiazdozbiór nieba i najbardziej rozpoznawalny znak południa; obok jego ramion leży ciemny Worek Węgla.', 'The smallest constellation in the sky and the best known marker of the south; the dark Coalsack lies beside its arms.', 'Das kleinste Sternbild des Himmels und das bekannteste Zeichen des Südens; neben seinen Armen liegt der dunkle Kohlensack.', 'La constelación más pequeña del cielo y la señal más reconocible del sur; junto a sus brazos está el oscuro Saco de Carbón.'],
 'Cygnus': ['Łabędź lecący wzdłuż Drogi Mlecznej; jego Deneb wieńczy Krzyż Północy, a Cygnus X-1 był pierwszym uznanym kandydatem na czarną dziurę.', 'The swan flying down the Milky Way; Deneb tops its Northern Cross, and Cygnus X-1 was the first accepted black hole candidate.', 'Der Schwan fliegt die Milchstraße entlang; Deneb krönt sein Kreuz des Nordens, und Cygnus X-1 war der erste anerkannte Kandidat für ein Schwarzes Loch.', 'El cisne vuela a lo largo de la Vía Láctea; Deneb corona su Cruz del Norte, y Cygnus X-1 fue el primer candidato aceptado a agujero negro.'],
 'Delphinus': ['Delfin, który wyłowił poetę Ariona; drobny romb gwiazd zwany Trumną Hioba.', 'The dolphin that rescued the poet Arion, a small diamond of stars known as Job’s Coffin.', 'Der Delfin, der den Dichter Arion rettete; eine kleine Sternraute, Hiobs Sarg genannt.', 'El delfín que rescató al poeta Arión, un pequeño rombo de estrellas llamado el Ataúd de Job.'],
 'Dorado': ['Złota ryba mieszcząca większość Wielkiego Obłoku Magellana i olbrzymią Mgławicę Tarantula.', 'The goldfish, holding most of the Large Magellanic Cloud and the enormous Tarantula Nebula.', 'Der Schwertfisch beherbergt den größten Teil der Großen Magellanschen Wolke und den gewaltigen Tarantelnebel.', 'El dorado alberga la mayor parte de la Gran Nube de Magallanes y la enorme Nebulosa de la Tarántula.'],
 'Draco': ['Smok wijący się wokół bieguna ekliptyki; jego Thuban był gwiazdą polarną w czasach budowy piramid.', 'The dragon coiling around the ecliptic pole; its Thuban was the pole star when the pyramids were built.', 'Der Drache windet sich um den Ekliptikpol; sein Thuban war zur Zeit des Pyramidenbaus der Polarstern.', 'El dragón se enrosca alrededor del polo de la eclíptica; su Thuban era la estrella polar cuando se construyeron las pirámides.'],
 'Equuleus': ['Źrebię, drugi najmniejszy gwiazdozbiór nieba, znany już Ptolemeuszowi.', 'The little horse, second smallest constellation in the sky, already known to Ptolemy.', 'Das Füllen, das zweitkleinste Sternbild des Himmels, bereits Ptolemäus bekannt.', 'El potrillo, la segunda constelación más pequeña del cielo, ya conocida por Ptolomeo.'],
 'Eridanus': ['Niebiańska rzeka wijąca się od stóp Oriona aż po jasnego Achernara przy południowym niebie.', "The celestial river, winding from Orion's foot all the way to brilliant Achernar in the far south.", 'Der Himmelsfluss windet sich vom Fuß des Orion bis zum hellen Achernar tief im Süden.', 'El río celeste serpentea desde el pie de Orión hasta el brillante Achernar en el extremo sur.'],
 'Fornax': ['Piec chemiczny Lacaille’a; puste dla oka pole, w którym Hubble wykonał swoje najgłębsze zdjęcia Wszechświata.', "Lacaille's chemical furnace: an empty field to the eye, and where Hubble took its deepest images of the universe.", 'Lacailles chemischer Ofen; ein für das Auge leeres Feld, in dem Hubble seine tiefsten Aufnahmen des Universums machte.', 'El horno químico de Lacaille; un campo vacío a la vista, donde Hubble tomó sus imágenes más profundas del universo.'],
 'Gemini': ['Bliźnięta Kastor i Polluks; tu Herschel odkrył Urana, a Tombaugh sfotografował Plutona.', 'The twins Castor and Pollux; Herschel found Uranus here, and Tombaugh photographed Pluto here.', 'Die Zwillinge Kastor und Pollux; hier entdeckte Herschel Uranus und Tombaugh fotografierte Pluto.', 'Los gemelos Cástor y Pólux; aquí Herschel descubrió Urano y Tombaugh fotografió Plutón.'],
 'Grus': ['Żuraw, wydzielony z ogona Ryby Południowej podczas holenderskiego kartowania południowego nieba.', 'The crane, cut from the tail of the Southern Fish during the Dutch charting of the southern sky.', 'Der Kranich, beim niederländischen Kartieren des Südhimmels vom Schwanz des Südlichen Fisches abgetrennt.', 'La grulla, separada de la cola del Pez Austral durante el trazado neerlandés del cielo austral.'],
 'Hercules': ['Klęczący heros; jego M13 to najjaśniejsza gromada kulista północnego nieba, cel słynnej wiadomości z Arecibo.', 'The kneeling hero; his M13 is the brightest globular cluster of the northern sky and the target of the Arecibo message.', 'Der kniende Held; sein M13 ist der hellste Kugelsternhaufen des Nordhimmels und Ziel der Arecibo-Botschaft.', 'El héroe arrodillado; su M13 es el cúmulo globular más brillante del cielo boreal y destino del mensaje de Arecibo.'],
 'Horologium': ['Zegar wahadłowy Lacaille’a, upamiętniający wynalazek Huygensa; wąski i słaby pas gwiazd.', "Lacaille's pendulum clock, honouring Huygens's invention; a narrow, faint strip of stars.", 'Lacailles Pendeluhr zu Ehren von Huygens’ Erfindung; ein schmaler, schwacher Sternstreifen.', 'El reloj de péndulo de Lacaille, en honor al invento de Huygens; una franja estrecha y débil de estrellas.'],
 'Hydra': ['Największy gwiazdozbiór nieba, rozciągnięty na ponad ćwierć jego obwodu, choć jasną gwiazdę ma tylko jedną.', 'The largest constellation in the sky, stretched over a quarter of its circumference, yet with only one bright star.', 'Das größte Sternbild des Himmels, über ein Viertel seines Umfangs gestreckt, doch mit nur einem hellen Stern.', 'La constelación más grande del cielo, extendida sobre un cuarto de su circunferencia, con una sola estrella brillante.'],
 'Hydrus': ['Mały wąż wodny wijący się między obydwoma Obłokami Magellana, blisko południowego bieguna.', 'The small water snake, winding between the two Magellanic Clouds near the southern pole.', 'Die Kleine Wasserschlange windet sich nahe dem Südpol zwischen den beiden Magellanschen Wolken.', 'La pequeña serpiente de agua serpentea entre las dos Nubes de Magallanes cerca del polo sur.'],
 'Indus': ['Indianin, jedna z figur wprowadzonych z relacji holenderskich żeglarzy pod koniec XVI wieku.', 'The Indian, one of the figures introduced from the reports of Dutch navigators late in the sixteenth century.', 'Der Indianer, eine der Figuren nach Berichten niederländischer Seefahrer des späten 16. Jahrhunderts.', 'El indio, una de las figuras introducidas a partir de los relatos de navegantes neerlandeses de finales del siglo XVI.'],
 'Lacerta': ['Jaszczurka, zygzak słabych gwiazd, którym Heweliusz wypełnił lukę między Łabędziem a Andromedą.', 'The lizard, a zigzag of faint stars with which Hevelius filled the gap between Cygnus and Andromeda.', 'Die Eidechse, ein Zickzack schwacher Sterne, mit dem Hevelius die Lücke zwischen Schwan und Andromeda füllte.', 'El lagarto, un zigzag de estrellas débiles con el que Hevelius llenó el hueco entre Cisne y Andrómeda.'],
 'Leo': ['Lew z sierpem gwiazd nad Regulusem; z jego wnętrza zdają się wybiegać listopadowe Leonidy.', 'The lion, its sickle of stars above Regulus; the November Leonids appear to stream out from inside it.', 'Der Löwe mit der Sternsichel über Regulus; aus seinem Inneren scheinen die Leoniden im November zu strömen.', 'El león, con su hoz de estrellas sobre Régulo; las Leónidas de noviembre parecen brotar de su interior.'],
 'Leo Minor': ['Mały lew, garść słabych gwiazd, którą Heweliusz wcisnął między Lwa a Wielką Niedźwiedzicę.', 'The little lion, a handful of faint stars Hevelius wedged between Leo and Ursa Major.', 'Der Kleine Löwe, eine Handvoll schwacher Sterne, die Hevelius zwischen Löwe und Großen Bären zwängte.', 'El león menor, un puñado de estrellas débiles que Hevelius encajó entre Leo y la Osa Mayor.'],
 'Lepus': ['Zając przycupnięty pod stopami Oriona, ścigany przez jego psy; kryje gromadę kulistą M79.', "The hare crouching under Orion's feet, chased by his dogs; it holds the globular cluster M79.", 'Der Hase kauert zu Füßen des Orion, von seinen Hunden gejagt; hier steht der Kugelsternhaufen M79.', 'La liebre agazapada a los pies de Orión, perseguida por sus perros; contiene el cúmulo globular M79.'],
 'Libra': ['Waga, jedyny nieożywiony znak zodiaku; jej gwiazdy nadal noszą arabskie nazwy szczypiec Skorpiona.', 'The scales, the only inanimate sign of the zodiac; its stars still carry the Arabic names of the scorpion’s claws.', 'Die Waage, das einzige unbelebte Tierkreiszeichen; ihre Sterne tragen noch die arabischen Namen der Skorpionsscheren.', 'La balanza, único signo inanimado del zodiaco; sus estrellas conservan los nombres árabes de las pinzas del escorpión.'],
 'Lupus': ['Wilk przebity włócznią Centaura, leżący w gęstym polu młodych gorących gwiazd.', 'The wolf, pierced by the centaur’s spear, set in a dense field of young hot stars.', 'Der Wolf, vom Speer des Zentauren durchbohrt, in einem dichten Feld junger heißer Sterne.', 'El lobo, atravesado por la lanza del centauro, en un denso campo de estrellas jóvenes y calientes.'],
 'Lynx': ['Ryś, o którym Heweliusz pisał, że trzeba rysich oczu, by go dostrzec; same słabe gwiazdy.', 'The lynx, of which Hevelius wrote that it takes the eyes of a lynx to see it; faint stars throughout.', 'Der Luchs, von dem Hevelius schrieb, man brauche Luchsaugen, um ihn zu sehen; durchweg schwache Sterne.', 'El lince, del que Hevelius escribió que hacen falta ojos de lince para verlo; solo estrellas débiles.'],
 'Lyra': ['Lutnia Orfeusza z jasną Wegą; między jej dolnymi gwiazdami leży pierścieniowa mgławica planetarna M57.', "Orpheus's lyre with brilliant Vega; the ring-shaped planetary nebula M57 sits between its lower stars.", 'Die Leier des Orpheus mit der hellen Wega; zwischen ihren unteren Sternen liegt der Ringnebel M57.', 'La lira de Orfeo con la brillante Vega; entre sus estrellas inferiores está la nebulosa anular M57.'],
 'Mensa': ['Góra Stołowa, jedyny gwiazdozbiór nazwany od ziemskiego miejsca; nakrywa go skraj Wielkiego Obłoku Magellana.', 'Table Mountain, the only constellation named after a place on Earth; the edge of the Large Magellanic Cloud caps it.', 'Der Tafelberg, das einzige nach einem irdischen Ort benannte Sternbild; der Rand der Großen Magellanschen Wolke krönt ihn.', 'La Mesa, única constelación con nombre de un lugar terrestre; el borde de la Gran Nube de Magallanes la corona.'],
 'Microscopium': ['Mikroskop, kolejny instrument Lacaille’a; pole niemal puste dla nieuzbrojonego oka.', "The microscope, another of Lacaille's instruments; a field all but empty to the unaided eye.", 'Das Mikroskop, ein weiteres Instrument Lacailles; ein für das bloße Auge nahezu leeres Feld.', 'El microscopio, otro instrumento de Lacaille; un campo casi vacío a simple vista.'],
 'Monoceros': ['Jednorożec w środku Trójkąta Zimowego; niepozorny dla oka, ale pełen mgławic Drogi Mlecznej.', 'The unicorn inside the Winter Triangle: unremarkable to the eye, yet crowded with Milky Way nebulae.', 'Das Einhorn im Wintersechseck-Dreieck: dem Auge unscheinbar, doch voller Milchstraßennebel.', 'El unicornio dentro del Triángulo de Invierno: discreto a la vista, pero repleto de nebulosas de la Vía Láctea.'],
 'Musca': ['Mucha, jedyny owad na niebie, tuż pod Krzyżem Południa na tle Drogi Mlecznej.', 'The fly, the only insect in the sky, just below the Southern Cross against the Milky Way.', 'Die Fliege, das einzige Insekt am Himmel, direkt unter dem Kreuz des Südens vor der Milchstraße.', 'La mosca, único insecto del cielo, justo bajo la Cruz del Sur sobre la Vía Láctea.'],
 'Norma': ['Węgielnica ciesielska; Lacaille utworzył ją z gwiazd zabranych Wilkowi i Skorpionowi.', "The carpenter's square, which Lacaille assembled from stars taken out of Lupus and Scorpius.", 'Das Winkelmaß, das Lacaille aus Sternen von Wolf und Skorpion zusammensetzte.', 'La escuadra de carpintero, que Lacaille formó con estrellas tomadas del Lobo y el Escorpión.'],
 'Octans': ['Oktant obejmujący południowy biegun niebieski; jego σ Octantis to gwiazda polarna tak słaba, że ledwie widoczna.', 'The octant, containing the south celestial pole; its Sigma Octantis is a pole star so faint it is barely visible.', 'Der Oktant enthält den südlichen Himmelspol; sein Sigma Octantis ist ein Polarstern, der kaum sichtbar ist.', 'El octante contiene el polo sur celeste; su Sigma Octantis es una estrella polar tan débil que apenas se ve.'],
 'Ophiuchus': ['Wężownik, przez którego Słońce przechodzi w listopadzie, choć nie należy do znaków zodiaku; kryje gwiazdę Barnarda.', "The serpent bearer, crossed by the Sun each November though it is not a zodiac sign; it holds Barnard's Star.", 'Der Schlangenträger, den die Sonne jeden November durchquert, obwohl er kein Tierkreiszeichen ist; hier steht Barnards Pfeilstern.', 'El serpentario, atravesado por el Sol cada noviembre aunque no es signo zodiacal; contiene la estrella de Barnard.'],
 'Orion': ['Myśliwy z pasem trzech gwiazd; czerwona Betelgeza i błękitny Rigel obejmują wielką mgławicę zawieszoną w jego mieczu.', 'The hunter with his belt of three stars; red Betelgeuse and blue Rigel flank the great nebula hanging in his sword.', 'Der Jäger mit dem Gürtel aus drei Sternen; die rote Beteigeuze und der blaue Rigel flankieren den großen Nebel in seinem Schwert.', 'El cazador con su cinturón de tres estrellas; la roja Betelgeuse y el azul Rigel flanquean la gran nebulosa de su espada.'],
 'Pavo': ['Paw z holenderskich wypraw; mieści jasną gromadę kulistą NGC 6752.', 'The peacock, from the Dutch voyages; it contains the bright globular cluster NGC 6752.', 'Der Pfau aus den niederländischen Fahrten; er enthält den hellen Kugelsternhaufen NGC 6752.', 'El pavo, de los viajes neerlandeses; contiene el brillante cúmulo globular NGC 6752.'],
 'Pegasus': ['Skrzydlaty koń rysowany jako Wielki Kwadrat; przy jednej z jego gwiazd znaleziono pierwszą planetę krążącą wokół gwiazdy podobnej do Słońca.', 'The winged horse, drawn as the Great Square; the first planet around a Sun-like star was found at one of its stars.', 'Das geflügelte Pferd, als Herbstviereck gezeichnet; an einem seiner Sterne fand man den ersten Planeten um einen sonnenähnlichen Stern.', 'El caballo alado, dibujado como el Gran Cuadrado; en una de sus estrellas se halló el primer planeta en torno a una estrella como el Sol.'],
 'Perseus': ['Bohater z głową Meduzy; jej oko, Algol, przygasa co niecałe trzy dni, gdy zaćmiewa je towarzysz.', 'The hero holding the head of Medusa; her eye, Algol, dims every few days as a companion eclipses it.', 'Der Held mit dem Haupt der Medusa; ihr Auge Algol verdunkelt sich alle knapp drei Tage durch einen Begleiter.', 'El héroe con la cabeza de Medusa; su ojo, Algol, se atenúa cada casi tres días al eclipsarlo una compañera.'],
 'Phoenix': ['Feniks odradzający się z popiołów, największa z figur wprowadzonych przez holenderskich żeglarzy.', 'The phoenix rising from its ashes, the largest of the figures introduced by the Dutch navigators.', 'Der aus der Asche steigende Phönix, die größte der von niederländischen Seefahrern eingeführten Figuren.', 'El fénix que renace de sus cenizas, la mayor de las figuras introducidas por los navegantes neerlandeses.'],
 'Pictor': ['Sztaluga malarza; przy jej β Pictoris sfotografowano jeden z pierwszych dysków pyłowych wokół obcej gwiazdy.', "The painter's easel; one of the first dust discs around another star was imaged at its Beta Pictoris.", 'Die Staffelei des Malers; an ihrem Beta Pictoris wurde eine der ersten Staubscheiben um einen fremden Stern abgebildet.', 'El caballete del pintor; en su Beta Pictoris se fotografió uno de los primeros discos de polvo en torno a otra estrella.'],
 'Pisces': ['Dwie ryby związane wstęgą; to w nich leży dziś punkt równonocy wiosennej.', 'Two fishes tied by a ribbon; the vernal equinox point now lies within them.', 'Zwei durch ein Band verbundene Fische; in ihnen liegt heute der Frühlingspunkt.', 'Dos peces unidos por una cinta; en ellos se sitúa hoy el punto vernal.'],
 'Piscis Austrinus': ['Ryba Południowa pijąca wodę wylewaną przez Wodnika; jej Fomalhaut jest otoczony pierścieniem pyłu.', 'The southern fish drinking the water poured by Aquarius; its Fomalhaut is ringed by a belt of dust.', 'Der Südliche Fisch trinkt das vom Wassermann ausgegossene Wasser; sein Fomalhaut ist von einem Staubring umgeben.', 'El Pez Austral bebe el agua vertida por Acuario; su Fomalhaut está rodeado por un anillo de polvo.'],
 'Puppis': ['Rufa okrętu Argo, przecięta jasnym pasem Drogi Mlecznej z licznymi gromadami otwartymi.', 'The stern of the ship Argo, crossed by a bright band of Milky Way full of open clusters.', 'Das Heck des Schiffs Argo, durchzogen von einem hellen Milchstraßenband voller offener Sternhaufen.', 'La popa del navío Argo, cruzada por una franja brillante de Vía Láctea llena de cúmulos abiertos.'],
 'Pyxis': ['Kompas żeglarski, dodany przez Lacaille’a obok szczątków rozdzielonego okrętu Argo.', "The mariner's compass, added by Lacaille beside the remains of the divided ship Argo.", 'Der Schiffskompass, von Lacaille neben den Resten des geteilten Schiffs Argo hinzugefügt.', 'La brújula del marinero, añadida por Lacaille junto a los restos del navío Argo dividido.'],
 'Reticulum': ['Sieć celownicza z okularu mikrometru Lacaille’a, uwieczniona jako mały romb gwiazd.', "The reticle from the eyepiece of Lacaille's micrometer, preserved as a small diamond of stars.", 'Das Fadenkreuz aus dem Okular von Lacailles Mikrometer, als kleine Sternraute verewigt.', 'El retículo del ocular del micrómetro de Lacaille, conservado como un pequeño rombo de estrellas.'],
 'Sagitta': ['Strzała, trzeci najmniejszy gwiazdozbiór nieba, lecąca przez Drogę Mleczną między Łabędziem a Orłem.', 'The arrow, third smallest constellation in the sky, flying across the Milky Way between Cygnus and Aquila.', 'Der Pfeil, das drittkleinste Sternbild, fliegt zwischen Schwan und Adler durch die Milchstraße.', 'La flecha, tercera constelación más pequeña, vuela por la Vía Láctea entre el Cisne y el Águila.'],
 'Sagittarius': ['Strzelec celujący w serce Skorpiona; za jego czajnikiem, w najgęstszym polu nieba, leży centrum Galaktyki.', "The archer aiming at the heart of Scorpius; the galactic centre lies past his teapot, in the densest field of the sky.", 'Der Schütze zielt auf das Herz des Skorpions; hinter seiner Teekanne, im dichtesten Feld des Himmels, liegt das Galaktische Zentrum.', 'El arquero apunta al corazón de Escorpio; tras su tetera, en el campo más denso del cielo, está el centro galáctico.'],
 'Scorpius': ['Skorpion z czerwonym Antaresem w miejscu serca; jego zakrzywiony ogon zanurza się w Drodze Mlecznej.', 'The scorpion, red Antares at its heart and its curved tail dipping into the Milky Way.', 'Der Skorpion mit dem roten Antares als Herz; sein gekrümmter Schwanz taucht in die Milchstraße.', 'El escorpión, con el rojo Antares por corazón y su cola curva sumergida en la Vía Láctea.'],
 'Sculptor': ['Pracownia rzeźbiarza otaczająca południowy biegun galaktyczny; stąd patrzy się poza dysk Drogi Mlecznej.', "The sculptor's studio, surrounding the south galactic pole; the view here looks clear out of the Milky Way's disc.", 'Das Atelier des Bildhauers umgibt den galaktischen Südpol; der Blick reicht hier aus der Milchstraßenscheibe hinaus.', 'El taller del escultor rodea el polo sur galáctico; la vista sale limpia del disco de la Vía Láctea.'],
 'Scutum': ['Tarcza Sobieskiego, jedyny gwiazdozbiór upamiętniający postać historyczną; leży na jasnym obłoku gwiazd.', "Sobieski's shield, the only constellation commemorating a historical person, set on a bright star cloud.", 'Der Schild des Sobieski, das einzige Sternbild zu Ehren einer historischen Person, auf einer hellen Sternwolke.', 'El escudo de Sobieski, única constelación que conmemora a una persona histórica, sobre una brillante nube estelar.'],
 'Serpens Caput': ['Głowa węża trzymanego przez Wężownika — jedyna figura nieba podzielona na dwie rozłączne części.', 'The head of the serpent held by Ophiuchus, the only sky figure split into two separate pieces.', 'Der Kopf der vom Schlangenträger gehaltenen Schlange - die einzige Himmelsfigur aus zwei getrennten Teilen.', 'La cabeza de la serpiente sostenida por Ofiuco, la única figura del cielo partida en dos piezas separadas.'],
 'Serpens Cauda': ['Ogon tego samego węża, po wschodniej stronie Wężownika; mieści Mgławicę Orzeł.', 'The tail of the same serpent, on the eastern side of Ophiuchus; it holds the Eagle Nebula.', 'Der Schwanz derselben Schlange, östlich des Schlangenträgers; hier liegt der Adlernebel.', 'La cola de la misma serpiente, al este de Ofiuco; contiene la Nebulosa del Águila.'],
 'Sextans': ['Sekstant Heweliusza, upamiętniający instrument, który spłonął w jego gdańskim obserwatorium.', "Hevelius's sextant, commemorating the instrument lost in the fire at his Gdańsk observatory.", 'Der Sextant des Hevelius, zum Gedenken an das Instrument, das in seiner Danziger Sternwarte verbrannte.', 'El sextante de Hevelius, en memoria del instrumento perdido en el incendio de su observatorio de Gdańsk.'],
 'Taurus': ['Byk z pomarańczowym Aldebaranem w oku; niesie na sobie Hiady i Plejady, a na końcu rogu Mgławicę Krab.', 'The bull, orange Aldebaran in its eye; it carries the Hyades and the Pleiades, and the Crab Nebula at one horn tip.', 'Der Stier mit dem orangen Aldebaran im Auge; er trägt Hyaden und Plejaden und an einer Hornspitze den Krebsnebel.', 'El toro, con el anaranjado Aldebarán en el ojo; lleva las Híades y las Pléyades, y la Nebulosa del Cangrejo en la punta de un cuerno.'],
 'Telescopium': ['Teleskop Lacaille’a, uszczuplony później przez sąsiadów; pozostała z niego uboga plama nieba.', "Lacaille's telescope, later trimmed by its neighbours; what remains is a poor patch of sky.", 'Lacailles Teleskop, später von den Nachbarn beschnitten; übrig blieb ein karges Himmelsfeld.', 'El telescopio de Lacaille, recortado luego por sus vecinos; queda una parcela pobre de cielo.'],
 'Triangulum': ['Wąski trójkąt znany już starożytnym; mieści galaktykę M33, trzecią co do wielkości w Grupie Lokalnej.', 'A narrow triangle known since antiquity; it holds M33, the third largest galaxy of the Local Group.', 'Ein schmales Dreieck, schon der Antike bekannt; es enthält M33, die drittgrößte Galaxie der Lokalen Gruppe.', 'Un triángulo estrecho conocido desde la antigüedad; contiene M33, la tercera galaxia mayor del Grupo Local.'],
 'Triangulum Australe': ['Trójkąt Południowy, jaśniejszy i regularniejszy od swojego północnego imiennika.', 'The southern triangle, brighter and more regular than its northern namesake.', 'Das Südliche Dreieck, heller und regelmäßiger als sein nördlicher Namensvetter.', 'El Triángulo Austral, más brillante y regular que su homónimo del norte.'],
 'Tucana': ['Tukan mieszczący Mały Obłok Magellana i gromadę 47 Tucanae, drugą co do jasności na niebie.', 'The toucan, holding the Small Magellanic Cloud and 47 Tucanae, the second brightest globular in the sky.', 'Der Tukan beherbergt die Kleine Magellansche Wolke und 47 Tucanae, den zweithellsten Kugelsternhaufen des Himmels.', 'El tucán alberga la Pequeña Nube de Magallanes y 47 Tucanae, el segundo globular más brillante del cielo.'],
 'Ursa Major': ['Wielka Niedźwiedzica z Wielkim Wozem; jego dwie zewnętrzne gwiazdy wskazują drogę do Gwiazdy Polarnej.', 'The great bear, containing the Plough; its two outer stars point the way to Polaris.', 'Der Große Bär mit dem Großen Wagen; seine beiden äußeren Sterne weisen zum Polarstern.', 'La Osa Mayor, con el Carro; sus dos estrellas exteriores señalan el camino a la Polar.'],
 'Ursa Minor': ['Mała Niedźwiedzica zakończona Gwiazdą Polarną, oddaloną dziś od bieguna o niecały stopień.', 'The little bear, tipped by Polaris, which now stands less than a degree from the pole.', 'Der Kleine Bär, angeführt vom Polarstern, der heute weniger als ein Grad vom Pol entfernt steht.', 'La Osa Menor, rematada por la Polar, hoy a menos de un grado del polo.'],
 'Vela': ['Żagle okrętu Argo; kryją pozostałość po supernowej i pulsar, jeden z najjaśniejszych w promieniach gamma.', 'The sails of the ship Argo, hiding a supernova remnant and a pulsar that is among the brightest in gamma rays.', 'Die Segel des Schiffs Argo verbergen einen Supernovaüberrest und einen der im Gammabereich hellsten Pulsare.', 'Las velas del navío Argo ocultan un remanente de supernova y un púlsar de los más brillantes en rayos gamma.'],
 'Virgo': ['Panna z kłosem Spiki; jej gromada galaktyk jest najbliższym wielkim skupiskiem, ku któremu spada Droga Mleczna.', 'The maiden holding the ear of wheat, Spica; her galaxy cluster is the nearest great swarm, the one the Milky Way is falling towards.', 'Die Jungfrau mit der Kornähre Spica; ihr Galaxienhaufen ist die nächste große Ansammlung, auf die die Milchstraße zufällt.', 'La virgen con la espiga, Spica; su cúmulo de galaxias es la agrupación grande más cercana, hacia la que cae la Vía Láctea.'],
 'Volans': ['Ryba latająca, umykająca Złotej Rybie; niewielka figura z holenderskich map południowego nieba.', 'The flying fish, escaping the goldfish; a small figure from the Dutch charts of the southern sky.', 'Der Fliegende Fisch, der dem Schwertfisch entkommt; eine kleine Figur der niederländischen Südhimmelkarten.', 'El pez volador, que huye del dorado; una figura pequeña de las cartas neerlandesas del cielo austral.'],
 'Vulpecula': ['Lisek Heweliusza; w nim leży Mgławica Hantle i miejsce odkrycia pierwszego pulsara.', "Hevelius's little fox; it contains the Dumbbell Nebula and the place where the first pulsar was found.", 'Das Füchschen des Hevelius; hier liegen der Hantelnebel und der Ort, an dem der erste Pulsar gefunden wurde.', 'La zorrita de Hevelius; contiene la Nebulosa Dumbbell y el lugar donde se halló el primer púlsar.']
});

export const deepSkyNotes = Object.freeze({
 'LMC': ['Galaktyka satelitarna Drogi Mlecznej odległa o około 160 tysięcy lat świetlnych; w niej wybuchła SN 1987A, najbliższa supernowa od czterech wieków.', 'A satellite galaxy of the Milky Way about 160 000 light years away; SN 1987A, the closest supernova in four centuries, went off here.', 'Eine Satellitengalaxie der Milchstraße in rund 160 000 Lichtjahren Entfernung; hier explodierte SN 1987A, die nächste Supernova seit vier Jahrhunderten.', 'Galaxia satélite de la Vía Láctea a unos 160 000 años luz; aquí estalló SN 1987A, la supernova más cercana en cuatro siglos.'],
 'Mel 25': ['Najbliższa gromada otwarta, około 150 lat świetlnych stąd; tworzy głowę Byka, choć jaśniejszy Aldebaran leży bliżej i tylko rzutuje się na nią.', 'The nearest open cluster, some 150 light years away; it forms the head of Taurus, though brighter Aldebaran lies closer and merely projects onto it.', 'Der nächstgelegene offene Sternhaufen, etwa 150 Lichtjahre entfernt; er bildet den Kopf des Stiers, während der hellere Aldebaran näher steht und sich nur davor projiziert.', 'El cúmulo abierto más cercano, a unos 150 años luz; forma la cabeza de Tauro, aunque el más brillante Aldebarán está más cerca y solo se proyecta sobre él.'],
 'η Car': ['Rozległy obszar gwiazdotwórczy wokół niestabilnej gwiazdy η Carinae, która w latach 40. XIX wieku stała się na chwilę drugą najjaśniejszą gwiazdą nieba.', 'A vast star-forming region around the unstable Eta Carinae, which briefly became the second brightest star in the sky in the 1840s.', 'Eine weite Sternentstehungsregion um den instabilen Stern Eta Carinae, der in den 1840er Jahren kurzzeitig der zweithellste Stern des Himmels war.', 'Una vasta región de formación estelar en torno a la inestable Eta Carinae, que en la década de 1840 fue brevemente la segunda estrella más brillante del cielo.'],
 'GalCtr': ['Kierunek na środek Drogi Mlecznej, około 26 tysięcy lat świetlnych stąd; kryje się tam czarna dziura Sagittarius A* o masie czterech milionów Słońc.', 'The direction of the centre of the Milky Way, some 26 000 light years away, where the four-million-solar-mass black hole Sagittarius A* sits.', 'Die Richtung zum Zentrum der Milchstraße, rund 26 000 Lichtjahre entfernt, wo das Schwarze Loch Sagittarius A* mit vier Millionen Sonnenmassen sitzt.', 'La dirección del centro de la Vía Láctea, a unos 26 000 años luz, donde se halla el agujero negro Sagitario A*, de cuatro millones de masas solares.'],
 'M 45': ['Plejady, młoda gromada odległa o około 440 lat świetlnych; gołym okiem widać zwykle sześć lub siedem gwiazd, w rzeczywistości jest ich ponad tysiąc.', 'The Pleiades, a young cluster about 440 light years away; the eye usually picks out six or seven stars where more than a thousand belong.', 'Die Plejaden, ein junger Haufen in etwa 440 Lichtjahren; das Auge erkennt meist sechs oder sieben Sterne, tatsächlich sind es über tausend.', 'Las Pléyades, cúmulo joven a unos 440 años luz; el ojo distingue seis o siete estrellas donde hay más de mil.'],
 'Mel 20': ['Ruchoma gromada wokół α Persei, luźne skupisko jasnych gorących gwiazd rozciągnięte na kilka stopni nieba.', 'The moving cluster around Alpha Persei, a loose gathering of bright hot stars spread over several degrees of sky.', 'Der bewegliche Haufen um Alpha Persei, eine lockere Ansammlung heller heißer Sterne über mehrere Grad Himmel verteilt.', 'El cúmulo móvil en torno a Alfa Persei, una agrupación laxa de estrellas calientes extendida varios grados.'],
 'Mel 111': ['Gromada Warkocza Bereniki, rozrzucona i bliska; jej gwiazdy widać gołym okiem jako delikatną mgiełkę pod ogonem Lwa.', "The Coma Berenices cluster, scattered and nearby; its stars show to the unaided eye as a soft haze under the lion's tail.", 'Der Coma-Haufen, weit gestreut und nahe; seine Sterne erscheinen dem bloßen Auge als sanfter Schleier unter dem Löwenschwanz.', 'El cúmulo de Coma Berenices, disperso y cercano; sus estrellas se ven a simple vista como una neblina bajo la cola del león.'],
 'IC 2602': ['Południowe Plejady, jasna gromada otwarta w Kilu, widoczna gołym okiem wokół gwiazdy θ Carinae.', 'The Southern Pleiades, a bright open cluster in Carina, visible to the unaided eye around the star Theta Carinae.', 'Die Südlichen Plejaden, ein heller offener Haufen im Kiel, mit bloßem Auge um Theta Carinae sichtbar.', 'Las Pléyades del Sur, cúmulo abierto brillante en la Quilla, visible a simple vista alrededor de Theta Carinae.'],
 'SMC': ['Mniejsza z dwóch galaktyk towarzyszących Drodze Mlecznej, około 200 tysięcy lat świetlnych stąd; to na jej gwiazdach zmiennych oparto pomiar odległości we Wszechświecie.', 'The smaller of the two galaxies attending the Milky Way, some 200 000 light years away; its variable stars underpinned the measurement of cosmic distances.', 'Die kleinere der beiden Begleitgalaxien der Milchstraße, rund 200 000 Lichtjahre entfernt; ihre Veränderlichen begründeten die Messung kosmischer Entfernungen.', 'La menor de las dos galaxias que acompañan a la Vía Láctea, a unos 200 000 años luz; sus estrellas variables fundaron la medida de distancias cósmicas.'],
 'IC 2391': ['Jasna, rzadka gromada otwarta w Żaglu, notowana już w X wieku przez perskiego astronoma Al-Sufiego.', 'A bright, sparse open cluster in Vela, already recorded in the tenth century by the Persian astronomer al-Sufi.', 'Ein heller, lockerer offener Haufen im Segel, bereits im 10. Jahrhundert vom persischen Astronomen al-Sufi verzeichnet.', 'Un cúmulo abierto brillante y disperso en Velas, ya registrado en el siglo X por el astrónomo persa al-Sufi.'],
 'NGC 6231': ['Bardzo młoda gromada w Skorpionie, licząca kilka milionów lat; jądro rozległej asocjacji gorących gwiazd Scorpius OB1.', 'A very young cluster in Scorpius, a few million years old, forming the core of the wide hot-star association Scorpius OB1.', 'Ein sehr junger Haufen im Skorpion, wenige Millionen Jahre alt; Kern der weiten Assoziation heißer Sterne Scorpius OB1.', 'Un cúmulo muy joven en Escorpio, de unos pocos millones de años; núcleo de la amplia asociación de estrellas calientes Scorpius OB1.'],
 'NGC 2451': ['Jasna gromada w Rufie skupiona wokół pomarańczowego olbrzyma; w rzeczywistości dwie gromady widziane w jednym kierunku.', 'A bright cluster in Puppis gathered around an orange giant, and in fact two clusters seen along one line of sight.', 'Ein heller Haufen im Achterdeck um einen orangen Riesen - tatsächlich zwei Haufen in einer Sichtlinie.', 'Un cúmulo brillante en Popa en torno a una gigante naranja; en realidad dos cúmulos en la misma línea de visión.'],
 'NGC 3532': ['Bogata gromada w Kilu, licząca setki gwiazd; pierwszy obiekt, na jaki skierowano Kosmiczny Teleskop Hubble’a.', 'A rich cluster in Carina of several hundred stars, and the first object the Hubble Space Telescope was pointed at.', 'Ein reicher Haufen im Kiel mit mehreren hundert Sternen; das erste Objekt, auf das das Hubble-Weltraumteleskop gerichtet wurde.', 'Un cúmulo rico en la Quilla con cientos de estrellas; el primer objeto al que apuntó el telescopio espacial Hubble.'],
 'M 44': ['Żłóbek, jedna z najbliższych gromad otwartych; starożytni traktowali jej zamglenie jako zapowiedź pogody.', 'The Beehive, one of the nearest open clusters; the ancients read its haziness as a forecast of the weather.', 'Die Praesepe, einer der nächsten offenen Haufen; die Antike las aus ihrer Trübung das Wetter.', 'El Pesebre, uno de los cúmulos abiertos más cercanos; los antiguos leían su turbidez como pronóstico del tiempo.'],
 'M 7': ['Gromada Ptolemeusza, odnotowana przez niego w 130 roku naszej ery; najbardziej południowy obiekt katalogu Messiera.', 'The Ptolemy Cluster, recorded by him in AD 130, and the southernmost object in the Messier catalogue.', 'Der Ptolemäus-Haufen, von ihm 130 n. Chr. verzeichnet; das südlichste Objekt des Messier-Katalogs.', 'El Cúmulo de Ptolomeo, registrado por él en el año 130; el objeto más austral del catálogo Messier.'],
 'M 31': ['Galaktyka Andromedy, około 2,5 miliona lat świetlnych stąd i największa w Grupie Lokalnej; zbliża się do nas i za kilka miliardów lat zderzy się z Drogą Mleczną.', 'The Andromeda Galaxy, about 2.5 million light years away and the largest in the Local Group; it is approaching, and will collide with the Milky Way in a few billion years.', 'Die Andromedagalaxie, rund 2,5 Millionen Lichtjahre entfernt und die größte der Lokalen Gruppe; sie nähert sich und wird in einigen Milliarden Jahren mit der Milchstraße verschmelzen.', 'La Galaxia de Andrómeda, a unos 2,5 millones de años luz y la mayor del Grupo Local; se acerca y chocará con la Vía Láctea dentro de unos miles de millones de años.'],
 'Cr 140': ['Rozległa, luźna gromada w Wielkim Psie, tuż na południe od Syriusza, dobrze widoczna przez lornetkę.', 'A wide, loose cluster in Canis Major just south of Sirius, well seen in binoculars.', 'Ein weiter, lockerer Haufen im Großen Hund südlich von Sirius, gut im Fernglas zu sehen.', 'Un cúmulo amplio y laxo en el Can Mayor al sur de Sirio, bien visible con prismáticos.'],
 'Cr 399': ['Wieszak, asteryzm w Liseku układający się w prostą kreskę z haczykiem; jego gwiazdy nie są ze sobą fizycznie związane.', 'The Coathanger, an asterism in Vulpecula shaped like a bar with a hook; its stars are not physically related.', 'Der Kleiderbügel, ein Asterismus im Füchschen aus einer Stange mit Haken; seine Sterne gehören physisch nicht zusammen.', 'La Percha, asterismo en la Zorra con forma de barra y gancho; sus estrellas no están relacionadas físicamente.'],
 'h Per': ['Zachodnia połowa Podwójnej Gromady w Perseuszu; obie liczą sobie zaledwie kilkanaście milionów lat i są ze sobą fizycznie związane.', 'The western half of the Double Cluster in Perseus; both are only a dozen or so million years old and physically bound to each other.', 'Die westliche Hälfte des Doppelsternhaufens im Perseus; beide sind nur gut zehn Millionen Jahre alt und physisch verbunden.', 'La mitad occidental del Cúmulo Doble de Perseo; ambos tienen apenas una decena de millones de años y están ligados físicamente.'],
 'χ Per': ['Wschodnia połowa Podwójnej Gromady; razem z h Persei widoczna gołym okiem jako podwójna mglista plamka.', 'The eastern half of the Double Cluster; together with h Persei it shows to the unaided eye as a twin misty patch.', 'Die östliche Hälfte des Doppelhaufens; zusammen mit h Persei dem bloßen Auge als doppelter Nebelfleck sichtbar.', 'La mitad oriental del Cúmulo Doble; junto con h Persei se ve a simple vista como una doble mancha nebulosa.'],
 'NGC 2516': ['Jasna gromada w Kilu zwana Diamentową Skrzynią Południa, z czerwonym olbrzymem pośród gorących białych gwiazd.', 'A bright cluster in Carina called the Southern Beehive, with a red giant among its hot white stars.', 'Ein heller Haufen im Kiel, die Südliche Bienenkorb genannt, mit einem Roten Riesen zwischen heißen weißen Sternen.', 'Un cúmulo brillante en la Quilla llamado el Panal del Sur, con una gigante roja entre estrellas blancas calientes.'],
 'NGC 2264': ['Gromada Choinka wraz z Mgławicą Stożek w Jednorożcu; wciąż rodzą się tu gwiazdy z otaczającego obłoku.', 'The Christmas Tree Cluster with the Cone Nebula in Monoceros, where stars are still forming out of the surrounding cloud.', 'Der Weihnachtsbaumhaufen mit dem Konusnebel im Einhorn, wo aus der umgebenden Wolke noch Sterne entstehen.', 'El Cúmulo del Árbol de Navidad con la Nebulosa del Cono en el Unicornio, donde aún nacen estrellas de la nube circundante.'],
 'ω Cen': ['Najjaśniejsza i najmasywniejsza gromada kulista Drogi Mlecznej, licząca miliony gwiazd; prawdopodobnie jądro pochłoniętej galaktyki karłowatej.', 'The brightest and most massive globular cluster of the Milky Way, with millions of stars; most likely the core of a swallowed dwarf galaxy.', 'Der hellste und massereichste Kugelsternhaufen der Milchstraße mit Millionen Sternen; wahrscheinlich der Kern einer verschluckten Zwerggalaxie.', 'El cúmulo globular más brillante y masivo de la Vía Láctea, con millones de estrellas; probablemente el núcleo de una galaxia enana engullida.'],
 'M 42': ['Wielka Mgławica Oriona, około 1300 lat świetlnych stąd; najbliższy duży obszar narodzin gwiazd, widoczny gołym okiem w mieczu Oriona.', "The Great Orion Nebula, about 1300 light years away: the nearest large stellar nursery, visible to the unaided eye in Orion's sword.", 'Der Große Orionnebel, rund 1300 Lichtjahre entfernt; die nächste große Sternenwiege, mit bloßem Auge im Schwert des Orion sichtbar.', 'La Gran Nebulosa de Orión, a unos 1300 años luz; la guardería estelar grande más cercana, visible a simple vista en la espada de Orión.'],
 '47 Tuc': ['Druga co do jasności gromada kulista nieba, o wyjątkowo zwartym jądrze; leży tuż obok Małego Obłoku Magellana, ale znacznie bliżej nas.', 'The second brightest globular cluster in the sky, with an exceptionally dense core; it lies beside the Small Magellanic Cloud but far closer to us.', 'Der zweithellste Kugelsternhaufen des Himmels mit außergewöhnlich dichtem Kern; er steht neben der Kleinen Magellanschen Wolke, ist uns aber weit näher.', 'El segundo cúmulo globular más brillante del cielo, de núcleo excepcionalmente denso; está junto a la Pequeña Nube de Magallanes, pero mucho más cerca.'],
 'NGC 2362': ['Zwarta, bardzo młoda gromada skupiona wokół jasnej gwiazdy τ Canis Majoris; liczy zaledwie kilka milionów lat.', 'A compact, very young cluster gathered around the bright star Tau Canis Majoris, only a few million years old.', 'Ein kompakter, sehr junger Haufen um den hellen Stern Tau Canis Majoris, nur wenige Millionen Jahre alt.', 'Un cúmulo compacto y muy joven en torno a la brillante Tau Canis Majoris, de solo unos millones de años.'],
 'M 6': ['Gromada Motyl w Skorpionie; jej gwiazdy układają się w rozpostarte skrzydła, a najjaśniejsza z nich jest pomarańczowym olbrzymem.', 'The Butterfly Cluster in Scorpius; its stars trace open wings, and its brightest member is an orange giant.', 'Der Schmetterlingshaufen im Skorpion; seine Sterne zeichnen ausgebreitete Flügel, das hellste Mitglied ist ein oranger Riese.', 'El Cúmulo de la Mariposa en Escorpio; sus estrellas dibujan alas abiertas y su miembro más brillante es una gigante naranja.'],
 'NGC 2244': ['Gromada w środku Mgławicy Rozeta; to jej gorące młode gwiazdy wydmuchały w obłoku okrągłą dziurę.', 'The cluster at the centre of the Rosette Nebula; its hot young stars blew the round cavity in the cloud.', 'Der Haufen im Zentrum des Rosettennebels; seine heißen jungen Sterne bliesen die runde Höhle in die Wolke.', 'El cúmulo en el centro de la Nebulosa Roseta; sus estrellas jóvenes y calientes abrieron la cavidad redonda en la nube.'],
 'M 8': ['Mgławica Laguna w Strzelcu, jeden z nielicznych obszarów gwiazdotwórczych widocznych gołym okiem; przecina ją ciemny pas pyłu.', 'The Lagoon Nebula in Sagittarius, one of the few star-forming regions visible to the unaided eye, split by a dark dust lane.', 'Der Lagunennebel im Schützen, eine der wenigen mit bloßem Auge sichtbaren Sternentstehungsregionen, von einem dunklen Staubband geteilt.', 'La Nebulosa de la Laguna en Sagitario, una de las pocas regiones de formación estelar visibles a simple vista, cortada por una banda oscura de polvo.'],
 'M 4': ['Jedna z najbliższych gromad kulistych, tuż obok Antaresa; przez teleskop rozpada się na pojedyncze gwiazdy łatwiej niż inne.', 'One of the nearest globular clusters, right beside Antares; a telescope resolves it into individual stars more readily than most.', 'Einer der nächstgelegenen Kugelsternhaufen, direkt neben Antares; ein Teleskop löst ihn leichter in Einzelsterne auf als die meisten.', 'Uno de los cúmulos globulares más cercanos, junto a Antares; un telescopio lo resuelve en estrellas individuales con más facilidad que otros.'],
 'M 33': ['Galaktyka Trójkąta, trzecia co do wielkości w Grupie Lokalnej; rozległa i o niskiej jasności powierzchniowej, więc trudniejsza do dostrzeżenia niż wskazuje jej wielkość gwiazdowa.', 'The Triangulum Galaxy, third largest in the Local Group; broad and low in surface brightness, so harder to see than its magnitude suggests.', 'Die Dreiecksgalaxie, drittgrößte der Lokalen Gruppe; ausgedehnt und flächenschwach, daher schwerer zu sehen, als ihre Helligkeit vermuten lässt.', 'La Galaxia del Triángulo, tercera mayor del Grupo Local; extensa y de bajo brillo superficial, más difícil de ver de lo que sugiere su magnitud.'],
 'M 16': ['Mgławica Orzeł w ogonie Węża; jej pyłowe kolumny, sfotografowane przez Hubble’a, stały się jednym z najbardziej znanych obrazów astronomii.', "The Eagle Nebula in the serpent's tail; its dust pillars, imaged by Hubble, became one of the best known pictures in astronomy.", 'Der Adlernebel im Schlangenschwanz; seine von Hubble aufgenommenen Staubsäulen wurden zu einem der bekanntesten Bilder der Astronomie.', 'La Nebulosa del Águila en la cola de la serpiente; sus pilares de polvo, fotografiados por Hubble, son una de las imágenes más conocidas de la astronomía.']
});

function note(table, key, language) {
 const row = table[key];
 if (!row) return null;
 // German and Spanish fall back to English rather than to the Polish source,
 // which is the more useful default for a reader who chose neither.
 return row[languageIndex[language] ?? 1] || row[1] || row[0];
}

export const constellationNote = (latinName, language = 'en') => note(constellationNotes, latinName, language);
export const deepSkyNote = (id, language = 'en') => note(deepSkyNotes, id, language);
